ALTER TABLE public.partidos ADD COLUMN jornada integer, ADD COLUMN pabellon text NOT NULL DEFAULT 'Pavillón Municipal de Guntín';
UPDATE public.partidos SET pabellon=lugar;
COMMENT ON COLUMN public.partidos.lugar IS 'DEPRECATED: replaced by pabellon';
ALTER TABLE public.partidos ALTER COLUMN competicion SET DEFAULT 'Primera Futgal · Grupo 2';
ALTER TABLE public.partidos ADD COLUMN resultado text GENERATED ALWAYS AS (CASE WHEN NOT jugado OR goles_favor IS NULL OR goles_contra IS NULL THEN NULL WHEN goles_favor>goles_contra THEN 'V' WHEN goles_favor=goles_contra THEN 'E' ELSE 'D' END) STORED;
CREATE TABLE public.clasificacion_club(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), jornada integer NOT NULL DEFAULT 0, posicion integer NOT NULL, actualizado_at timestamptz NOT NULL DEFAULT now(), actualizado_por uuid, CONSTRAINT posicion_positiva CHECK(posicion>0), CONSTRAINT jornada_positiva CHECK(jornada>=0));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.clasificacion_club TO authenticated;
GRANT ALL ON public.clasificacion_club TO service_role;
ALTER TABLE public.clasificacion_club ENABLE ROW LEVEL SECURITY;
CREATE POLICY clasificacion_lectura ON public.clasificacion_club FOR SELECT TO authenticated USING(public.has_club_role('directiva') OR public.mi_socio() IS NOT NULL OR public.mi_patrocinador() IS NOT NULL);
CREATE POLICY clasificacion_directiva ON public.clasificacion_club FOR ALL TO authenticated USING(public.has_club_role('directiva')) WITH CHECK(public.has_club_role('directiva'));
ALTER TABLE public.ajustes_club ADD COLUMN url_clasificacion_futgal text NOT NULL DEFAULT 'https://www.futgal.es/pnfg/NPcd/NFG_VisClasificacion?cod_primaria=1000120&codcompeticion=26991388&codgrupo=26991389&cod_agrupacion=1';
CREATE OR REPLACE VIEW public.ajustes_club_publicos AS SELECT id,whatsapp_club,nombre_club,temporada_actual,url_clasificacion_futgal FROM public.ajustes_club;
CREATE VIEW public.estadisticas_liga WITH(security_invoker=true) AS SELECT count(*)::int AS pj,count(*) FILTER(WHERE resultado='V')::int AS g,count(*) FILTER(WHERE resultado='E')::int AS e,count(*) FILTER(WHERE resultado='D')::int AS p,(3*count(*) FILTER(WHERE resultado='V')+count(*) FILTER(WHERE resultado='E'))::int AS puntos,coalesce(sum(goles_favor),0)::int AS goles_favor,coalesce(sum(goles_contra),0)::int AS goles_contra,coalesce((SELECT array_agg(resultado ORDER BY fecha_hora DESC,id) FROM(SELECT resultado,fecha_hora,id FROM public.partidos WHERE jugado AND resultado IS NOT NULL ORDER BY fecha_hora DESC,id LIMIT 5) ultimos),ARRAY[]::text[]) AS racha FROM public.partidos WHERE jugado AND resultado IS NOT NULL;
GRANT SELECT ON public.estadisticas_liga TO authenticated,service_role;
CREATE FUNCTION public.guardar_resultado_partido(p_id uuid,p_favor integer,p_contra integer,p_posicion integer DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE j integer; BEGIN IF NOT public.has_club_role('directiva') THEN RAISE EXCEPTION 'Solo Directiva'; END IF; IF p_favor<0 OR p_contra<0 OR p_favor IS NULL OR p_contra IS NULL THEN RAISE EXCEPTION 'Goles no válidos'; END IF; UPDATE public.partidos SET goles_favor=p_favor,goles_contra=p_contra,jugado=true WHERE id=p_id RETURNING jornada INTO j; IF NOT FOUND THEN RAISE EXCEPTION 'Partido no encontrado'; END IF; IF p_posicion IS NOT NULL THEN INSERT INTO public.clasificacion_club(jornada,posicion,actualizado_por) VALUES(coalesce(j,0),p_posicion,auth.uid()); END IF; END $$;
REVOKE ALL ON FUNCTION public.guardar_resultado_partido(uuid,integer,integer,integer) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.guardar_resultado_partido(uuid,integer,integer,integer) TO authenticated;
ALTER TABLE public.avisos ADD CONSTRAINT aviso_tipo_informativo CHECK(tipo IN ('club','ventaja','otro')) NOT VALID;
ALTER TABLE public.partidos ADD CONSTRAINT partido_goles_validos CHECK ((goles_favor IS NULL OR goles_favor>=0) AND (goles_contra IS NULL OR goles_contra>=0) AND (NOT jugado OR (goles_favor IS NOT NULL AND goles_contra IS NOT NULL))) NOT VALID;